package com.vandorlabs.neoforge.programmer;
import com.google.gson.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.phys.*;
import net.minecraft.world.phys.shapes.*;
/** Actual engine DDA and all ray contexts, while physical and selected grids remain full cubes. */
final class ProgrammerWorldPickingChecks {
 private static final ClipContext.Block[] MODES={ClipContext.Block.OUTLINE,ClipContext.Block.COLLIDER,ClipContext.Block.VISUAL};
 private static int checks;private static volatile double collisionSink;
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Programmer World picking: "+why);}
 private static Vec3 point(JsonArray a){return new Vec3(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}
 private static void install(ServerLevel level,NativeProgrammerBlock block,BlockPos root,Direction facing){for(int x=-2;x<4;x++)for(int y=-2;y<4;y++)for(int z=-2;z<4;z++){var pos=root.offset(x,y,z);level.getChunkAt(pos);level.removeBlock(pos,false);}for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(root,facing,part);level.setBlock(pos,block.defaultBlockState().setValue(NativeProgrammerBlock.FACING,facing).setValue(NativeProgrammerBlock.PART,part),3);var state=level.getBlockState(pos);var collision=state.getCollisionShape(level,pos);var outline=state.getShape(level,pos);need(collision==outline&&collision==state.getShape(level,pos),"cached shape identity");need(collision.bounds().equals(Shapes.block().bounds())&&collision.toAabbs().size()==1&&outline.toAabbs().size()==1,"full physical and outline grid");need(level.getBlockCollisions(null,new AABB(pos.getX()+.1,pos.getY()+.1,pos.getZ()+.1,pos.getX()+.9,pos.getY()+.9,pos.getZ()+.9)).iterator().hasNext(),"actual full engine collision");}}
 private static void collisionBatch(ServerLevel level,AABB box,int count){double sum=0;for(int i=0;i<count;i++)for(var shape:level.getBlockCollisions(null,box))sum+=shape.max(Direction.Axis.Y);collisionSink=sum;}
 private static long[] collisionCost(ServerLevel level,AABB box){collisionBatch(level,box,5000);var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),bytes=bean.getThreadAllocatedBytes(thread),started=System.nanoTime();collisionBatch(level,box,10000);long time=System.nanoTime()-started,allocated=bean.getThreadAllocatedBytes(thread)-bytes;return new long[]{allocated,time};}
 private static void collisionCosts(ServerLevel level,NativeProgrammerBlock block,BlockPos root,Direction facing){var layout=NativeProgrammerLayout.of(facing);var box=new AABB(root.getX()+layout.originX()+.1,root.getY()+.1,root.getZ()+layout.originZ()+.1,root.getX()+layout.originX()+layout.width()-.1,root.getY()+1.9,root.getZ()+layout.originZ()+layout.depth()-.1);var authored=collisionCost(level,box);need(collisionSink>0,"measured actual authored block collisions");for(int part=0;part<4;part++)level.setBlock(NativeProgrammerBlock.cell(root,facing,part),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);var cube=collisionCost(level,box);need(collisionSink>0,"measured equivalent full cube collisions");System.out.println("[vandorlabs][programmer-collision-cost] calls=10000 authoredBytes="+authored[0]+" cubeBytes="+cube[0]+" authoredNs="+authored[1]+" cubeNs="+cube[1]);for(int part=0;part<4;part++)level.removeBlock(NativeProgrammerBlock.cell(root,facing,part),false);}
 static void run(ServerLevel level,NativeProgrammerBlock block,BlockPos root)throws Exception{var shift=new Vec3(root.getX()-7,root.getY()-80,root.getZ()+11);Direction installed=null;int cases=0,hits=0;try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_PROGRAMMER_WORLD_RAYS_REFERENCE")))){String line;while((line=reader.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();if(row.has("golden")){need(row.get("golden").getAsString().equals("ba684407a8d4cffedc2b87accb8cf3f43371015c5bdf68a9d3f3b242d3c03bb9"),"actual Source World corpus");continue;}var facing=Direction.valueOf(row.get("facing").getAsString());if(installed!=facing){install(level,block,root,facing);installed=facing;}Vec3 from=point(row.getAsJsonArray("from")).add(shift),to=point(row.getAsJsonArray("to")).add(shift);for(var context:MODES){var actual=level.clip(new ClipContext(from,to,context,ClipContext.Fluid.NONE,CollisionContext.empty()));need((actual.getType()==HitResult.Type.BLOCK)==row.has("hit"),"engine hit existence case="+cases+" context="+context);if(row.has("hit")){var expected=point(row.getAsJsonArray("hit")).add(shift);var p=row.getAsJsonArray("cell");var expectedCell=new BlockPos(p.get(0).getAsInt()+root.getX()-7,p.get(1).getAsInt()+root.getY()-80,p.get(2).getAsInt()+root.getZ()+11);need(actual.getLocation().distanceToSqr(expected)<1e-16&&actual.getBlockPos().equals(expectedCell)&&actual.getDirection().name().equals(row.get("side").getAsString()),"engine nearest point/cell/normal case="+cases+" context="+context+" actual="+actual.getLocation()+" cell="+actual.getBlockPos()+" expected="+expected+" cell="+expectedCell);var authored=block.trace(actual.getBlockPos(),level.getBlockState(actual.getBlockPos()),from,to);need(authored!=null&&authored.slot()==row.get("slot").getAsInt()&&authored.group().equals(row.get("group").getAsString()),"same authoritative socket/group");}}need(level.clip(new ClipContext(from,to,ClipContext.Block.FALLDAMAGE_RESETTING,ClipContext.Fluid.NONE,CollisionContext.empty())).getType()==HitResult.Type.MISS,"ordinary Iron does not reset fall damage");if(row.has("hit"))hits++;cases++;}}need(cases==6936&&hits==4160,"all released World rays");collisionCosts(level,block,root,installed);level.removeBlock(root,false);System.out.println("[vandorlabs][programmer-world-picking] PASS SourceCases="+cases+" hits="+hits+" contexts="+MODES.length+" checks="+checks);}
}
